"""Homothety determined by a point pair and three circle positions from pages 346–347."""
import argparse
import json
from homothety_centers import RULE
from homothetic_grid_figures import polygons
from homothetic_lines_circles import exact_circles
from polygon_similarity_intro import entry
from rotated_circles_lines import diagram
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/given-homothety-image.json'
CAP='T обозначает центр O. Штрихи указывают образы с индексом 1. Сравни как направления от T, так и расстояния.'


def times(p,k):return tuple(x*k for x in p)


def transfer_scene(title,k,given,helper=None):
    t=(0,0);a=(2,0);points={'T':t,'A':a,'A′':times(a,k),'M':given,'M′':times(given,k)}
    sides=[('T','A'),('T','A′'),('T','M'),('T','M′')]
    if helper:
        points['B']=helper;points['B′']=times(helper,k)
        sides.extend([('T','B'),('T','B′'),('A','B'),('A′','B′'),('B','M'),('B′','M′')])
    else:sides.extend([('A','M'),('A′','M′')])
    return diagram(title,points,sides)


def point_from_pair():
    return entry(1321,None,[346],'Гомотетию задают центр O и известная пара A→A₁. Построй образ M₁ произвольной точки M. Учти положение M как вне прямой OA, так и на ней.',
        'Если M не лежит на OA, проведи OM и через A₁ прямую, параллельную AM. Их пересечение — M₁, поскольку образ AM проходит через A₁ и параллелен AM. Если M лежит на OA, выбери B вне этой прямой и тем же способом построй B₁. Через B₁ проведи параллель к BM; она пересечёт OA в M₁. Если M=O, образ равен O, а если M=A, ответ уже дан. Для однозначного задания коэффициента исходная A должна отличаться от O. Если A=A₁≠O, вся гомотетия тождественна.',
        [('Используй известный образ A','На первой схеме прямая AM не проходит через T. Через A′ проведи параллель AM и найди её пересечение с TM. Убедись, что оно совпало с M′.','При отрицательном коэффициенте используется вся прямая TM: искомая точка может оказаться на противоположном луче.'),
         ('Обойди вырожденное пересечение','Во второй модели T,A,M коллинеарны. Введи вспомогательную B вне их прямой, сначала построй B′. Затем B′M′ должна быть параллельна BM. Здесь TA=2, TA′=4 и TM=3. Вычисли TM′.','Проведённая через A′ прямая, параллельная AM, совпала бы с TM и не определила бы единственную M′.'),
         ('Проверь знак новой пары','На третьей схеме A и A′ лежат по разные стороны от T, TA=2, TA′=3 и TM=4. Выведи коэффициент и расстояние TM′.','Отношение длин даёт модуль 3/2; расположение A и A′ задаёт знак минус.')],
        [transfer_scene('M вне прямой через T и A',1.5,(1,2)),transfer_scene('M на той же прямой: вспомогательная B',2,(3,0),(1,2)),transfer_scene('Отрицательный коэффициент по A и A′',-1.5,(0,4))],
        [('Какова TM′ во втором построении?','6','Коэффициент 4/2=2, значит TM′=6.'),('Какова TM′ в третьем построении?','6','4·3/2=6; направление противоположно.')],
        RULE,'Если две прямые для пересечения совпали, введи отдельную точку вне OA и построй её образ первым.',CAP,refs=[133,134])


def parallelogram():
    shape={'A':(2,0),'B':(4,0),'C':(5,2),'D':(3,2)}
    return entry(1322,None,[346],'Даны параллелограмм ABCD, центр O и точка A₁ на прямой OA. Построй образ всего параллелограмма при гомотетии, переводящей A в A₁.',
        'Пара O,A,A₁ определяет знак и модуль коэффициента: в векторной записи OA₁=k·OA. Используя образы точек или параллели, построй B₁ и D₁. Четвёртая вершина C₁ лежит на пересечении прямой через B₁, параллельной AD, и прямой через D₁, параллельной AB. Соедини A₁,B₁,C₁,D₁. Уравнение векторов OC₁=k·OC даёт независимую проверку четвёртой вершины.',
        [('Установи знак и масштаб','В первой модели A и A′ лежат на одном луче из T. Найди общий коэффициент, затем отметь образы B и D. Если один луч совпал с TA, используй известное отношение расстояний.','При произвольном условии O может не лежать внутри параллелограмма. Центром всё равно служит O.'),
         ('Замкни стороны параллелями','Во второй модели AB=2 и k=3/2. Вычисли A′B′. После этого через B′ и D′ проведи нужные параллели и проверь пересечение в C′.','Диагональ или сторона, проведённая без соответствующей параллели, не задаёт четвёртую вершину однозначно.'),
         ('Попробуй отрицательный коэффициент','В новой схеме k=−2 и AB=3. Найди длину A′B′ и проверь, что вектор направлен противоположно AB.','Коэффициент со знаком нужен для построения точек, его модуль — для длины стороны.')],
        [polygons('Дострой параллелограмм по трём образам',shape,(0,0),2),polygons('Коэффициент 3/2 по A и A′',shape,(0,0),1.5),polygons('Новые исходные вершины и k=−2',{'A':(1,0),'B':(4,0),'C':(5,1),'D':(2,1)},(0,0),-2)],
        [('Какова A′B′ при AB=2 и k=3/2?','3','2·3/2=3.'),('Какова новая A′B′ при AB=3, k=−2?','6','Длина умножается на |−2|.')],
        RULE,'Сначала установи A₁, B₁ и D₁. Стороны образа параллельны соответствующим сторонам исходного параллелограмма.',CAP,refs=[133,134])


def ring_scene(title,c,r,k,through=None):
    rpoint=through or (c[0],c[1]+r);c1=times(c,k);r1=times(rpoint,k)
    pts={'T':(0,0),'C':c,'R':rpoint,'C′':c1,'R′':r1}
    for j,(center,rad) in enumerate([(c,r),(c1,abs(k)*r)]):
        for i,(dx,dy) in enumerate([(rad,0),(-rad,0),(0,rad),(0,-rad)]):
            pts[f'bound{j}{i}']=(center[0]+dx,center[1]+dy)
    return diagram(title,pts,[('C','R'),('C′','R′'),('T','C'),('T','C′'),('T','R'),('T','R′')])


def circle_from_pair():
    c=entry(1323,None,[346,347],'Даны центр O, пара A→A₁ и окружность, проходящая через A. Построй окружность, которая ей соответствует при заданной гомотетии.',
        'Найди центр C исходной окружности и построй его образ C₁ по известной паре A→A₁, как в №1321. Так как точка A лежит на исходной окружности, A₁ лежит на окружности-образе. Поэтому достаточно провести окружность с центром C₁ через A₁. Её радиус C₁A₁=|k|·CA. Если C=O, центр остаётся неподвижен. Если C лежит на прямой OA, можно воспользоваться вспомогательной точкой вне этой прямой.',
        [('Сопоставь центры фигуры и преобразования','Найди C, а затем C′. В первой схеме A лежит на окружности и A′ — заранее известная точка её образа. T обозначает центр гомотетии.','Проводить окружность из A′ нельзя: A′ известно как точка её границы.'),
         ('Определи радиус по образу точки','Во второй модели CA=2 и коэффициент 3/2. Вычисли C′A′. Затем укажи, как провести окружность, не измеряя её радиус отдельно.','Расстояние между центрами T и C′ не подходит на роль радиуса.'),
         ('Смени знак и радиус','В третьей модели CA=3 и k=−2. Каков диаметр окружности-образа? Укажи также, почему A′ на ней осталась.','У нового радиуса длина 6. В вопросе нужно удвоить эту величину.')],
        [ring_scene('Центр C′ и данная точка A′', (3,2),2,-.5,(3,0)),ring_scene('Проверка радиуса при k=3/2',(4,2),2,1.5,(4,0)),ring_scene('Другая окружность при k=−2',(2,3),3,-2,(2,0))],
        [('Каков радиус образа при CA=2 и k=3/2?','3','2·3/2=3.'),('Каков новый диаметр при CA=3, k=−2?','12','2·|−2|·3=12.')],
        RULE,'Сначала построй C₁, затем проведи окружность именно через A₁.',CAP,refs=[133,134])
    c=exact_circles(c);m=c['visualization']['model']
    for key,label in m['labels'].items():
        if label in ('R','R′'):m['labels'][key]=label.replace('R','A')
    return c


def center_position(part):
    on=part!='в';k={'а':.5,'б':-.5,'в':3}[part]
    if on:
        direct=k>0;side='на том же луче OC' if direct else 'на противоположном луче к OC'
        contact='внутреннее' if direct else 'внешнее'
        place='целиком лежит в исходном круге и касается его границы в O' if direct else 'лежит с другой стороны от общей касательной по сравнению с исходной окружностью'
        task=f'Точка O лежит на окружности с центром C и радиусом r. Построй фигуру-образ при гомотетии с центром O и коэффициентом {"1/2" if direct else "−1/2"}.'
        proof=f'Центр C₁ строим {side} на расстоянии r/2 от O. Радиус новой окружности тоже равен r/2. Точка O остаётся на месте и принадлежит обеим окружностям. Их центры и O коллинеарны, поэтому в O у них общая касательная. Касание {contact}: новая окружность {place}.'
        hops='между O и C' if direct else 'за O на продолжении CO'
        scenes=[ring_scene('Общая точка T и новый центр', (2,0),2,k),ring_scene('Исходный радиус 4', (0,4),4,k),ring_scene('Новая конфигурация с радиусом 6', (3.6,4.8),6,k)]
        steps=[('Определи, где лежит новый центр',f'Поскольку TC=r, расстояние TC′ равно r/2. Центр C′ находится {hops}. Посмотри, почему через T пройдут обе окружности.','При отрицательном коэффициенте нельзя оставить C′ между T и C. При положительном половинном коэффициенте нельзя переносить C′ на противоположный луч.'),
               ('Проверь радиус','Во втором примере исходный радиус 4. Найди радиус образа и сравни его с расстоянием от T до C′.','Точка T остаётся общей, поэтому расстояние TC′ должно в точности равняться новому радиусу.'),
               ('Проверь другую исходную окружность','В третьей модели начальный радиус равен 6. Найди диаметр окружности-образа. Определи вид касания в T.','У нового радиуса длина 3, но для диаметра берутся два радиуса.')];checks=[('Каков новый радиус при r=4?','2','4/2=2.'),('Каков новый диаметр при r=6?','6','Два новых радиуса дают 6.')]
    else:
        task='Центр гомотетии O не лежит на данной окружности с центром C. Построй образ при коэффициенте 3. Учти, что O может находиться внутри или снаружи окружности.'
        proof='Если C≠O, отложи на луче OC расстояние OC₁=3OC. Проведи из C₁ окружность радиуса 3r. Если C=O, центр не меняется и строится концентрическая окружность радиуса 3r. Нахождение O вне самой линии окружности допускает и внутренние, и внешние точки. Общей точкой обеих окружностей O в этом подпункте служить не может.'
        scenes=[ring_scene('T вне диска', (4,0),1,3),ring_scene('T внутри диска, но не совпадает с C', (1,0),2,3),ring_scene('T совпал с C', (0,0),3,3)]
        steps=[('Найди настоящий образ центра','В первой модели центр гомотетии вне диска. Отложи утроенное TC на том же луче. Из найденного C′ строй окружность утроенного радиуса.','«Не лежит на окружности» означает не принадлежит её границе; это не обязательно внешняя точка диска.'),
               ('Проверь внутреннюю точку','Во второй модели T внутри диска и TC=1 при радиусе 2. Найди радиус образа; отдельно проверь, что TC′=3.','Не путай радиус 2 с расстоянием от T до C, равным 1.'),
               ('Проверь совпадение центров','В третьем примере T=C, исходный радиус равен 3. Каков диаметр образа?','Если центр совпал с T, он не должен никуда перемещаться. Увеличивается только радиус.')];checks=[('Каков новый радиус при r=2?','6','3·2=6.'),('Каков новый диаметр при r=3?','18','2·3·3=18.')]
    return exact_circles(entry(1324,part,[347],task,proof,steps,scenes,checks,RULE,'Сравни положение центра O с границей окружности. Отдельно вычисли OC₁ и радиус образа.',CAP,refs=[133,134]))


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[point_from_pair(),parallelogram(),circle_from_pair(),*[center_position(p) for p in 'абв']]
    for c in rows:
        m=c['visualization']['model']
        for key,label in m['labels'].items():
            if label in ('U','W'):m['labelOffsets'][key]=[-3 if label=='U' else 3,-4]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
